// The owner-approved category hierarchy (three levels at most). Single source of truth for:
//   * the demo catalogue (src/data/seed.ts)
//   * supabase/seed.sql and the category migration (generated by `npm run seed:sql`)
// Slugs of categories that already existed in the previous catalogue are kept, so product links survive.
// `keepAr: true` = the slug existed before and its current Arabic name still matches the new English name,
// so the migration leaves name_ar alone. Empty `ar` = no approved Arabic translation yet (storefront falls back to English).
import type { CategoryRecord } from "../types/catalog.ts";

