export type FlatCategory = CategoryRecord & { keepAr: boolean };

export function flattenApproved(): FlatCategory[] {
  const out: FlatCategory[] = [];
  const walk = (nodes: Node[], parent: string | null) =>
    nodes.forEach((n, i) => {
      out.push({ slug: n.slug, name: { en: n.en, ar: n.ar ?? "" }, parent, sort: i, active: true, keepAr: !!n.keepAr });
      walk(n.children ?? [], n.slug);
    });
  walk(approvedTree, null);
  return out;
}
